package mz.bam.seeky.android;
import android.content.*;import android.graphics.*;import com.googlecode.tesseract.android.TessBaseAPI;import java.io.*;import java.net.*;import java.util.function.BooleanSupplier;
/** On-device, one-page OCR. Only public language-model files are downloaded. */
final class OcrEngine {
 interface Progress{void update(String state);}
 static final String[] LANGS={"por","eng"},HASHES={"c4932b937207a9514b7514d518b931a99938c02a28a5a5a553f8599ed58b7deb","7d4322bd2a7749724879683fc3912cb542f19906c83bcc1a52132556427170b2"};
 volatile TessBaseAPI active;volatile int confidence;
 static File root(Context c){File root=new File(c.getFilesDir(),"ocr");new File(root,"tessdata").mkdirs();return root;}
 static File model(Context c,String language){if(!language.equals("por")&&!language.equals("eng"))throw new IllegalArgumentException();return new File(new File(root(c),"tessdata"),language+".traineddata");}
 static synchronized void install(Context c,String lang,BooleanSupplier cancelled,Progress progress)throws Exception{File target=model(c,lang);int index=lang.equals("eng")?1:0;if(target.isFile()&&StudyFiles.hash(target).equals(HASHES[index]))return;File temp=new File(target.getPath()+".part");HttpURLConnection con=null;try{con=(HttpURLConnection)new URL("https://cdn.jsdelivr.net/gh/tesseract-ocr/tessdata_fast@4.1.0/"+lang+".traineddata").openConnection();con.setConnectTimeout(20000);con.setReadTimeout(20000);con.setRequestProperty("Accept-Encoding","identity");if(con.getResponseCode()!=200)throw new IOException("Não foi possível descarregar os dados OCR. Verifique a ligação.");long length=con.getContentLengthLong(),received=0;if(length>10485760)throw new IOException("Dados OCR acima do limite.");try(InputStream in=con.getInputStream();FileOutputStream out=new FileOutputStream(temp)){byte[] buffer=new byte[32768];long shown=-1;for(int n;(n=in.read(buffer))!=-1;){if(cancelled.getAsBoolean())throw new InterruptedIOException();received+=n;if(received>10485760)throw new IOException("Dados OCR acima do limite.");out.write(buffer,0,n);long percent=length>0?received*100/length:received/65536;if(percent!=shown){shown=percent;progress.update("A descarregar OCR · "+(length>0?percent+"%":received/1024+" KB"));}}out.getFD().sync();}if(!StudyFiles.hash(temp).equals(HASHES[index]))throw new IOException("Os dados OCR não passaram a verificação. Actualize o Seeky e tente novamente.");java.nio.file.Files.move(temp.toPath(),target.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}finally{if(con!=null)con.disconnect();temp.delete();}}
 String recognise(Context c,Bitmap image,String language,BooleanSupplier cancelled,Progress progress)throws Exception{install(c,language,cancelled,progress);if(cancelled.getAsBoolean())throw new InterruptedIOException();TessBaseAPI api=new TessBaseAPI();try{progress.update("A reconhecer esta página…");if(!api.init(root(c).getPath()+File.separator,language,TessBaseAPI.OEM_LSTM_ONLY))throw new IOException("Não foi possível iniciar o OCR.");synchronized(this){if(cancelled.getAsBoolean())throw new InterruptedIOException();active=api;}api.setImage(image);if(cancelled.getAsBoolean())throw new InterruptedIOException();String text=api.getUTF8Text();confidence=Math.max(0,Math.min(100,api.meanConfidence()));if(cancelled.getAsBoolean())throw new InterruptedIOException();if(text==null||text.trim().isEmpty())throw new IOException("Não foi reconhecido texto. Tente uma imagem mais nítida.");return text.trim();}finally{synchronized(this){active=null;api.recycle();}}}
 synchronized void cancel(){TessBaseAPI api=active;if(api!=null)try{api.stop();}catch(IllegalStateException ignored){}}
 private OcrEngine(){}static OcrEngine create(){return new OcrEngine();}
}
